# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
detect_gui_tool() {
    if [ "$FORCE_MODE" = "cli" ]; then
        GUI_TOOL="cli"
        return
    fi
    if [ "$FORCE_MODE" = "tui" ]; then
        if command -v dialog >/dev/null 2>&1; then
            GUI_TOOL="dialog"
        elif command -v whiptail >/dev/null 2>&1; then
            GUI_TOOL="whiptail"
        else
            GUI_TOOL="cli"
        fi
        return
    fi
    # Ø±Ø³ÙˆÙ…ÙŠ Ø£ÙˆÙ„Ø§Ù‹
    if [ -n "$DISPLAY" ] || [ -n "$WAYLAND_DISPLAY" ]; then
        if command -v zenity >/dev/null 2>&1; then
            GUI_TOOL="zenity"
            return
        elif command -v kdialog >/dev/null 2>&1; then
            GUI_TOOL="kdialog"
            return
        fi
    fi
    # Ø·Ø±ÙÙŠØ© Ø«Ø§Ù†ÙŠØ§Ù‹
    if command -v dialog >/dev/null 2>&1; then
        GUI_TOOL="dialog"
    elif command -v whiptail >/dev/null 2>&1; then
        GUI_TOOL="whiptail"
    else
        GUI_TOOL="cli"
    fi
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# ØªØ­Ù„ÙŠÙ„ Ø§Ù„Ø£ÙˆØ§Ù…Ø±
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
while [ $# -gt 0 ]; do
    case "$1" in
        --tui)    FORCE_MODE="tui" ;;
        --cli)    FORCE_MODE="cli" ;;
        --dir)    INSTALL_DIR="$2"; shift ;;
        --help|-h)
            echo "Ù…Ø«Ø¨Øª Ù„ØºØ© Øµ â€” Linux Installer v${VERSION}"
            echo ""
            echo "Ø§Ù„Ø§Ø³ØªØ®Ø¯Ø§Ù…: $0 [Ø®ÙŠØ§Ø±Ø§Øª]"
            echo "  --tui       ÙˆØ¶Ø¹ Ø§Ù„Ø·Ø±ÙÙŠØ© Ø§Ù„Ù†ØµÙŠØ©"
            echo "  --cli       ÙˆØ¶Ø¹ Ø³Ø·Ø± Ø§Ù„Ø£ÙˆØ§Ù…Ø±"
            echo "  --dir DIR   Ù…Ø¬Ù„Ø¯ Ø§Ù„ØªØ«Ø¨ÙŠØª"
            echo "  --help      Ø¹Ø±Ø¶ Ø§Ù„Ù…Ø³Ø§Ø¹Ø¯Ø©"
            exit 0
            ;;
        *) echo "Ø®ÙŠØ§Ø± ØºÙŠØ± Ù…Ø¹Ø±ÙˆÙ: $1"; exit 1 ;;
    esac
    shift
done

detect_gui_tool

