gui_select_dir() {
    case "$GUI_TOOL" in
        zenity)
            INSTALL_DIR=$(zenity --file-selection --directory \
                --title="Ø§Ø®ØªØ± Ù…Ø¬Ù„Ø¯ Ø§Ù„ØªØ«Ø¨ÙŠØª" \
                --filename="$DEFAULT_INSTALL_DIR/" 2>/dev/null) || INSTALL_DIR="$DEFAULT_INSTALL_DIR"
