        kdialog)
            INSTALL_DIR=$(kdialog --getexistingdirectory "$DEFAULT_INSTALL_DIR" 2>/dev/null) || INSTALL_DIR="$DEFAULT_INSTALL_DIR"
            ;;
        dialog)
            INSTALL_DIR=$(dialog --title "Ù…Ø¬Ù„Ø¯ Ø§Ù„ØªØ«Ø¨ÙŠØª" --inputbox "\nØ£Ø¯Ø®Ù„ Ù…Ø¬Ù„Ø¯ Ø§Ù„ØªØ«Ø¨ÙŠØª:" 10 60 "$DEFAULT_INSTALL_DIR" 3>&1 1>&2 2>&3) || INSTALL_DIR="$DEFAULT_INSTALL_DIR"
