gui_progress() {
    local pct="$1"
    local msg="$2"
    case "$GUI_TOOL" in
        zenity)
            echo "$pct"
            echo "# $msg"
            ;;
        cli)
            local bar_len=40
            local filled=$((pct * bar_len / 100))
            local empty=$((bar_len - filled))
            printf "\r  [${GREEN}"
            printf '%0.sâ–ˆ' $(seq 1 $filled 2>/dev/null) 2>/dev/null || true
            printf "${NC}"
            printf '%0.sâ–‘' $(seq 1 $empty 2>/dev/null) 2>/dev/null || true
            printf "] %3d%% %s" "$pct" "$msg"
            ;;
    esac
}

