    esac
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Ø§Ø³ØªØ®Ø±Ø§Ø¬ Ø§Ù„Ø¨ÙŠØ§Ù†Ø§Øª Ø§Ù„Ù…ÙØ¶Ù…Ù†Ø©
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__$/{print NR + 1; exit 0;}' "$0")

extract_archive() {
    local dest="$1"
    tail -n +"$ARCHIVE_LINE" "$0" | tar xzf - -C "$dest" 2>/dev/null
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Ø¹Ù…Ù„ÙŠØ© Ø§Ù„ØªØ«Ø¨ÙŠØª
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
do_install() {
    mkdir -p "$INSTALL_DIR"
    mkdir -p "$INSTALL_DIR/bin"
    mkdir -p "$INSTALL_DIR/lib/sad-lang"
    
    if [ "$GUI_TOOL" = "zenity" ]; then
        (
            gui_progress 10 "Ø§Ø³ØªØ®Ø±Ø§Ø¬ Ø§Ù„Ù…Ù„ÙØ§Øª..."
            extract_archive "/tmp/sad-install-$$"
            
            gui_progress 30 "Ù†Ø³Ø® Ø§Ù„Ù…Ù„ÙØ§Øª Ø§Ù„ØªÙ†ÙÙŠØ°ÙŠØ©..."
            local src="/tmp/sad-install-$$/sad-1.0.0-linux-x64"
            cp "$src/bin/"* "$INSTALL_DIR/bin/" 2>/dev/null || true
            
            gui_progress 50 "Ù†Ø³Ø® Ø§Ù„Ù…ÙƒØªØ¨Ø© Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ©..."
            cp -r "$src/lib/sad-lang/stdlib" "$INSTALL_DIR/lib/sad-lang/" 2>/dev/null || true
            
            gui_progress 70 "Ø¥Ø¹Ø¯Ø§Ø¯ Ø§Ù„Ù…Ø³Ø§Ø±Ø§Øª..."
            setup_path
            
            gui_progress 90 "Ø¥Ù†Ø´Ø§Ø¡ Ø§Ù„Ø±ÙˆØ§Ø¨Ø·..."
            create_desktop_entry
            
            gui_progress 100 "Ø§ÙƒØªÙ…Ù„ Ø§Ù„ØªØ«Ø¨ÙŠØª!"
            sleep 1
        ) | zenity --progress --title="ØªØ«Ø¨ÙŠØª Ù„ØºØ© Øµ" --width=400 \
            --auto-close --no-cancel 2>/dev/null
    else
        echo -e "\n${CYAN}  Ø¨Ø¯Ø¡ Ø§Ù„ØªØ«Ø¨ÙŠØª...${NC}\n"
        
        gui_progress 10 "Ø§Ø³ØªØ®Ø±Ø§Ø¬ Ø§Ù„Ù…Ù„ÙØ§Øª..."
        mkdir -p "/tmp/sad-install-$$"
        extract_archive "/tmp/sad-install-$$"
        echo ""
        
        gui_progress 30 "Ù†Ø³Ø® Ø§Ù„Ù…Ù„ÙØ§Øª Ø§Ù„ØªÙ†ÙÙŠØ°ÙŠØ©..."
        local src="/tmp/sad-install-$$/sad-1.0.0-linux-x64"
        cp "$src/bin/"* "$INSTALL_DIR/bin/" 2>/dev/null || true
        echo ""
        
        gui_progress 50 "Ù†Ø³Ø® Ø§Ù„Ù…ÙƒØªØ¨Ø© Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ©..."
        cp -r "$src/lib/sad-lang/stdlib" "$INSTALL_DIR/lib/sad-lang/" 2>/dev/null || true
        echo ""
        
        gui_progress 70 "Ø¥Ø¹Ø¯Ø§Ø¯ Ø§Ù„Ù…Ø³Ø§Ø±Ø§Øª..."
        setup_path
        echo ""
        
        gui_progress 90 "Ø¥Ù†Ø´Ø§Ø¡ Ø§Ù„Ø±ÙˆØ§Ø¨Ø·..."
        create_desktop_entry
        echo ""
        
        gui_progress 100 "Ø§ÙƒØªÙ…Ù„ Ø§Ù„ØªØ«Ø¨ÙŠØª!"
        echo ""
    fi
    
    # ØªÙ†Ø¸ÙŠÙ
    rm -rf "/tmp/sad-install-$$"
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Ø¥Ø¹Ø¯Ø§Ø¯ PATH
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
setup_path() {
    local bin_dir="$INSTALL_DIR/bin"
    local path_line="export PATH=\"$bin_dir:\$PATH\""
    local sad_home="export SAD_HOME=\"$INSTALL_DIR\""
    
    for rc_file in "$HOME/.bashrc" "$HOME/.zshrc" "$HOME/.profile"; do
        if [ -f "$rc_file" ]; then
            if ! grep -q "SAD_HOME" "$rc_file" 2>/dev/null; then
                echo "" >> "$rc_file"
                echo "# Ù„ØºØ© Øµ / Sad Programming Language" >> "$rc_file"
                echo "$sad_home" >> "$rc_file"
                echo "$path_line" >> "$rc_file"
            fi
        fi
    done
    
    # ØªØµØ¯ÙŠØ± Ù„Ù„Ø¬Ù„Ø³Ø© Ø§Ù„Ø­Ø§Ù„ÙŠØ©
    export PATH="$bin_dir:$PATH"
    export SAD_HOME="$INSTALL_DIR"
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Ø¥Ù†Ø´Ø§Ø¡ Ø§Ø®ØªØµØ§Ø± Ø³Ø·Ø­ Ø§Ù„Ù…ÙƒØªØ¨
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
create_desktop_entry() {
    local desktop_dir="${XDG_DATA_HOME:-$HOME/.local/share}/applications"
    mkdir -p "$desktop_dir"
    
    cat > "$desktop_dir/sad-lang.desktop" <<EOF
[Desktop Entry]
Name=Sad Language REPL
Name[ar]=REPL Ù„ØºØ© Øµ
Comment=Arabic Programming Language Interactive Console
Comment[ar]=Ø§Ù„Ø·Ø±ÙÙŠØ© Ø§Ù„ØªÙØ§Ø¹Ù„ÙŠØ© Ù„Ù„ØºØ© Øµ
Exec=$INSTALL_DIR/bin/sad-repl
Icon=utilities-terminal
Terminal=true
Type=Application
Categories=Development;IDE;
Keywords=sad;programming;arabic;Ø¨Ø±Ù…Ø¬Ø©;Ø¹Ø±Ø¨ÙŠ;
EOF
}

# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Ø§Ù„ØªÙ†ÙÙŠØ° Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
main() {
    # Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† ÙˆØ¬ÙˆØ¯ Ø§Ù„Ø¨ÙŠØ§Ù†Ø§Øª Ø§Ù„Ù…ÙØ¶Ù…Ù†Ø©
    if [ -z "$ARCHIVE_LINE" ]; then
        echo -e "${RED}Ø®Ø·Ø£: Ù‡Ø°Ø§ Ø§Ù„Ù…Ù„Ù Ù„ÙŠØ³ Ù…Ø«Ø¨ØªØ§Ù‹ ØµØ§Ù„Ø­Ø§Ù‹ â€” Ù„Ø§ ØªÙˆØ¬Ø¯ Ø¨ÙŠØ§Ù†Ø§Øª Ù…ÙØ¶Ù…Ù†Ø©.${NC}"
        exit 1
    fi
    
    gui_welcome
    
    if [ -z "$INSTALL_DIR" ]; then
        gui_select_dir
    fi
    
    if ! gui_confirm; then
        echo "ØªÙ… Ø¥Ù„ØºØ§Ø¡ Ø§Ù„ØªØ«Ø¨ÙŠØª."
        exit 0
    fi
    
    do_install
    gui_done
}

main
exit 0

